import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: process.env.DB_SSL === 'true' ? { rejectUnauthorized: true } : false
});

// Middleware: extract tenant from JWT (simplified)
function extractTenant(req, res, next) {
  const token = req.headers['x-tenant-token'];
  if (!token) return res.status(401).json({ error: 'Missing tenant token' });
  try {
    const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64').toString());
    req.tenantId = payload.tenant_id;
    req.userRole = payload.role;
    next();
  } catch (e) {
    res.status(401).json({ error: 'Invalid token' });
  }
}

// Search endpoint with dynamic filtering
app.get('/api/v2/assets/search', extractTenant, async (req, res) => {
  try {
    const { category, status, sort_by, order, limit } = req.query;

    // Base query with tenant isolation
    let query = `SELECT id, name, category, status, metadata, created_at 
                 FROM assets WHERE tenant_id = $1`;
    const params = [req.tenantId];
    let paramIdx = 2;

    // Apply filters
    if (category) {
      query += ` AND category = $${paramIdx}`;
      params.push(category);
      paramIdx++;
    }
    if (status) {
      query += ` AND status = $${paramIdx}`;
      params.push(status);
      paramIdx++;
    }

    // Dynamic sort - validated against allowlist... partially
    const allowedSortFields = ['name', 'created_at', 'category', 'status'];
    if (sort_by) {
      // NOTE: sort_by is used in ORDER BY - cannot use parameterized queries for identifiers
      if (allowedSortFields.includes(sort_by.split(' ')[0].toLowerCase())) {
        const direction = order === 'desc' ? 'DESC' : 'ASC';
        query += ` ORDER BY ${sort_by} ${direction}`;
      } else {
        query += ` ORDER BY created_at DESC`;
      }
    } else {
      query += ` ORDER BY created_at DESC`;
    }

    // Limit
    const safeLimit = Math.min(parseInt(limit) || 50, 200);
    query += ` LIMIT ${safeLimit}`;

    const result = await pool.query(query, params);

    // Audit log
    await pool.query(
      'INSERT INTO audit_log (tenant_id, action, query_hash, ts) VALUES ($1, $2, $3, NOW())',
      [req.tenantId, 'asset_search', crypto.createHash('sha256').update(query).digest('hex')]
    );

    res.json({ 
      data: result.rows,
      meta: { total: result.rowCount, limit: safeLimit }
    });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Bulk update endpoint
app.patch('/api/v2/assets/bulk', extractTenant, async (req, res) => {
  const { asset_ids, updates } = req.body;
  if (!Array.isArray(asset_ids) || asset_ids.length === 0) {
    return res.status(400).json({ error: 'asset_ids required' });
  }
  if (asset_ids.length > 100) {
    return res.status(400).json({ error: 'Max 100 assets per batch' });
  }

  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const allowedFields = ['status', 'category', 'metadata'];
    const setClauses = [];
    const setParams = [req.tenantId];
    let idx = 2;

    for (const [key, value] of Object.entries(updates)) {
      if (allowedFields.includes(key)) {
        setClauses.push(`${key} = $${idx}`);
        setParams.push(value);
        idx++;
      }
    }

    if (setClauses.length === 0) {
      await client.query('ROLLBACK');
      return res.status(400).json({ error: 'No valid fields to update' });
    }

    const idPlaceholders = asset_ids.map((_, i) => `$${idx + i}`).join(',');
    setParams.push(...asset_ids);

    const updateQuery = `UPDATE assets SET ${setClauses.join(', ')}, updated_at = NOW() 
                         WHERE tenant_id = $1 AND id IN (${idPlaceholders})`;
    const result = await client.query(updateQuery, setParams);
    await client.query('COMMIT');

    res.json({ updated: result.rowCount });
  } catch (err) {
    await client.query('ROLLBACK');
    res.status(500).json({ error: 'Update failed' });
  } finally {
    client.release();
  }
});

app.listen(process.env.PORT || 3000);
